import type { RuntimeInstructionV1, RuntimeSceneV1 } from "@world-studio/project-compiler";
import {
  DEFAULT_PRNG_SEED,
  DEFAULT_INSTRUCTION_BUDGET,
  MAX_CALL_STACK_DEPTH,
