  MAX_META_PROGRESS_IDS_PER_DOMAIN,
  RUNTIME_STATE_SCHEMA_VERSION,
  RUNTIME_VERSION,
  type CreateRuntimeOptionsV1,
  type CreateRuntimeResultV1,
  type RuntimeChoiceOptionV1,
  type RuntimeCursorV1,
